import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse(`{"title":"ApptiveTeams — Tips and troubleshooting","description":"Why teams, tabs, tiles, or branding aren't showing up in the app.","frontmatter":{"title":"ApptiveTeams — Tips and troubleshooting","description":"Why teams, tabs, tiles, or branding aren't showing up in the app."},"headers":[],"relativePath":"en/apptiveteams/fehlerbehebung.md","filePath":"en/apptiveteams/fehlerbehebung.md","lastUpdated":1787319236000}`),n={name:"en/apptiveteams/fehlerbehebung.md"};function r(s,e,d,h,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="tips-and-troubleshooting" tabindex="-1">Tips and troubleshooting <a class="header-anchor" href="#tips-and-troubleshooting" aria-label="Permalink to &quot;Tips and troubleshooting&quot;">​</a></h1><p>ApptiveTeams doesn&#39;t report configuration errors — it simply <strong>omits</strong> anything faulty. A missing tab is almost always a Key or required-field problem.</p><h2 id="the-app-doesn-t-show-a-team" tabindex="-1">The app doesn&#39;t show a team <a class="header-anchor" href="#the-app-doesn-t-show-a-team" aria-label="Permalink to &quot;The app doesn&#39;t show a team&quot;">​</a></h2><p>Two causes are possible:</p><ol><li>The Space doesn&#39;t have the category <code>apptiveTeams</code>. → <a href="/en/apptiveteams/team-space">Setting up the Team Space</a></li><li>The signed-in person isn&#39;t a member of the Space. → <a href="/en/zusammenarbeit/personen-einladen">Invite people</a></li></ol><h2 id="the-bottom-tab-bar-doesn-t-appear" tabindex="-1">The bottom tab bar doesn&#39;t appear <a class="header-anchor" href="#the-bottom-tab-bar-doesn-t-appear" aria-label="Permalink to &quot;The bottom tab bar doesn&#39;t appear&quot;">​</a></h2><p>The navigation bar only shows once there are <strong>two valid tabs</strong>. Check that at least two rows in the <code>tabs</code> Grid have all required fields filled in — a row with a missing icon doesn&#39;t count.</p><h2 id="a-tab-tile-or-card-is-missing" tabindex="-1">A tab, tile, or card is missing <a class="header-anchor" href="#a-tab-tile-or-card-is-missing" aria-label="Permalink to &quot;A tab, tile, or card is missing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Why</th></tr></thead><tbody><tr><td>Are all required fields filled in?</td><td>Rows with gaps are skipped</td></tr><tr><td>Are field Keys spelled exactly right?</td><td>Case matters</td></tr><tr><td>For tabs: is <code>type</code> correct?</td><td>Only <code>TilesGrid</code>, <code>CardList</code>, and <code>WebView</code> are valid</td></tr><tr><td>For tiles/cards: is <code>actionType</code> correct?</td><td>An unknown value makes the row unusable</td></tr><tr><td>Is a filtered View linked?</td><td>The filter might be hiding the row</td></tr></tbody></table><h2 id="logo-or-color-isn-t-applied" tabindex="-1">Logo or color isn&#39;t applied <a class="header-anchor" href="#logo-or-color-isn-t-applied" aria-label="Permalink to &quot;Logo or color isn&#39;t applied&quot;">​</a></h2><p>In the <code>config</code> Grid, both <code>logo</code> <strong>and</strong> <code>primaryColor</code> must be filled in — if one is missing, the entire row is ignored and the app starts with no branding at all.</p><p>The color must be a hex value like <code>#1565C0</code>. Also keep in mind that only the <strong>first row</strong> of the Grid is evaluated.</p><h2 id="icons-aren-t-displayed" tabindex="-1">Icons aren&#39;t displayed <a class="header-anchor" href="#icons-aren-t-displayed" aria-label="Permalink to &quot;Icons aren&#39;t displayed&quot;">​</a></h2><p>Tab and tile icons must be <strong>SVG files</strong> — a PNG or JPG won&#39;t render. Since the app tints the icons, single-color SVGs without their own fill colors work best.</p><h2 id="a-webview-tab-stays-blank" tabindex="-1">A WebView tab stays blank <a class="header-anchor" href="#a-webview-tab-stays-blank" aria-label="Permalink to &quot;A WebView tab stays blank&quot;">​</a></h2><p>Some websites block being displayed in embedded views. Open the address in the device&#39;s browser for comparison. If it opens there but not in the app, the target page is blocking embedding — in that case, a tile with <code>externalLink</code> is the only option.</p><h2 id="changes-don-t-show-up-in-the-app" tabindex="-1">Changes don&#39;t show up in the app <a class="header-anchor" href="#changes-don-t-show-up-in-the-app" aria-label="Permalink to &quot;Changes don&#39;t show up in the app&quot;">​</a></h2><p>Tap the <strong>refresh icon</strong> in the top right, or restart the app. The configuration isn&#39;t continuously reloaded.</p><h2 id="created-by-doesn-t-show-the-right-person" tabindex="-1">&quot;Created by&quot; doesn&#39;t show the right person <a class="header-anchor" href="#created-by-doesn-t-show-the-right-person" aria-label="Permalink to &quot;&quot;Created by&quot; doesn&#39;t show the right person&quot;">​</a></h2><p>The tile or card is probably using <code>externalLink</code>. Only <code>internalLink</code> passes the signed-in person along to the form. → <a href="/en/apptiveteams/kacheln-und-karten#action-types">Tiles and cards</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/team-space">Setting up the Team Space</a></li><li><a href="/en/apptiveteams/tabs">Setting up tabs</a></li><li><a href="/en/fehlerbehebung/haeufige-fehlermeldungen">Common error messages</a></li></ul>',22)])])}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
